#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define TABLE_SIZE 32768

typedef struct {
    uint64_t keys[TABLE_SIZE];
    unsigned char used[TABLE_SIZE];
} Set;

static Set prefixes[11];
static Set suffixes[11];

static uint64_t encode(const char *s, int start, int length) {
    uint64_t value = 0;
    for (int i = 0; i < length; i++) {
        value = value * 26 + (uint64_t)(s[start + i] - 'a');
    }
    return value;
}

static uint64_t hash_value(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static int contains(const Set *set, uint64_t key) {
    uint32_t index = (uint32_t)hash_value(key) & (TABLE_SIZE - 1);
    while (set->used[index]) {
        if (set->keys[index] == key) return 1;
        index = (index + 1) & (TABLE_SIZE - 1);
    }
    return 0;
}

static void insert(Set *set, uint64_t key) {
    uint32_t index = (uint32_t)hash_value(key) & (TABLE_SIZE - 1);
    while (set->used[index]) {
        if (set->keys[index] == key) return;
        index = (index + 1) & (TABLE_SIZE - 1);
    }
    set->used[index] = 1;
    set->keys[index] = key;
}

int main(void) {
    int n;
    char s[11];

    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%10s", s);

        if (contains(&prefixes[10], encode(s, 0, 10))) {
            printf("%s\n", s);
            return 0;
        }

        for (int split = 1; split <= 9; split++) {
            if (contains(&suffixes[10 - split], encode(s, 0, 10 - split)) &&
                contains(&prefixes[split], encode(s, 10 - split, split))) {
                printf("%s\n", s);
                return 0;
            }
        }

        for (int length = 1; length <= 10; length++) {
            insert(&prefixes[length], encode(s, 0, length));
            insert(&suffixes[length], encode(s, 10 - length, length));
        }
    }

    printf("ok\n");
    return 0;
}
